<template><admin-layout><Head :title="$t(&quot;UMI 原机制影子核验&quot;)"/><main class="ub-page"><div class="ub-heading"><div><span class="ub-eyebrow">UMI / SNAPSHOT REPLAY</span><h1>{{ $t("原机制逐户核验") }}</h1><p>{{report.snapshot_date}} {{ $t("原资料 ·") }} {{report.accounts}} {{ $t("个账户 · 仅读取，不发放资金") }}</p></div><a :href="route('admin.umi.business')">{{ $t("返回业务管理 ↗") }}</a></div><section class="ub-notice">{{ $t(report.note) }}</section><div class="ub-grid"><article v-for="(n,k) in report.matched" :key="k" class="ub-card ub-metric"><span>{{names[k]}}</span><strong>{{n}} / {{report.accounts}}</strong><small>{{ $t("匹配数 / 范围内账户数") }}</small></article></div><section class="ub-card"><h2>{{ $t("快照当日汇总") }}</h2><dl><div><dt>{{ $t("线性释放") }}</dt><dd>{{fmt(report.linear_total)}} UMI</dd></div><div><dt>{{ $t("团队级差候选") }}</dt><dd>{{fmt(report.team_total)}} UMI</dd></div></dl><p>{{ $t("本页使用原日量、原层级和原收盘本金核验；每日业务结算使用上一日实际余额。两者不能互相替代。") }}</p><a :href="route('admin.umi.business.shadow')+'?format=json'">{{ $t('Download full verification JSON') }}</a></section><section class="ub-card"><h2>{{ $t("逐户结果") }}</h2><form @submit.prevent="$inertia.get(route('admin.umi.business.shadow'),{search:query,result})" class="ub-filter"><label>{{ $t("筛选原 UID") }}<input v-model.trim="query" inputmode="numeric" maxlength="100"/></label><label>{{ $t('Result') }}<themed-select v-model="result"><option value="">{{ $t('All') }}</option><option value="matched">{{ $t('Matched') }}</option><option value="review">{{ $t('待核对') }}</option></themed-select></label><button>{{ $t('Search') }}</button><Link :href="route('admin.umi.business.shadow')">{{ $t('Reset') }}</Link></form><div class="ub-table"><table><thead><tr><th>{{ $t("原 UID / 上级") }}</th><th>{{ $t("个人 / 团队 / 小区") }}</th><th>{{ $t("原等级候选") }}</th><th>{{ $t("当日实际 / 反推") }}</th><th>{{ $t("差额") }}</th><th>{{ $t("核验") }}</th></tr></thead><tbody><tr v-for="r in report.rows.data" :key="r.uid"><td><a :href="route('admin.umi.account',r.uid)">{{r.uid}}</a><small>{{ $t("上级") }} {{r.parent}}</small><small v-if="r.root_candidate">{{ $t("根账户候选字段") }}</small></td><td>{{fmt(r.personal)}}<small>{{fmt(r.team)}} / {{fmt(r.small_area)}}</small></td><td>V{{r.rank}}</td><td>{{fmt(r.actual_today)}}<small>{{fmt(r.candidate_today)}}</small></td><td>{{fmt(r.delta)}}</td><td><small v-for="(ok,k) in r.checks" :key="k" :class="ok?'ub-ok':'ub-bad'">{{names[k]}} {{ok?'✓':$t("待核")}}</small></td></tr></tbody></table></div><nav class="ub-pages"><Link v-if="report.rows.prev_page_url" :href="report.rows.prev_page_url" preserve-scroll>{{ $t('Previous') }}</Link><span>{{report.rows.current_page}} / {{report.rows.last_page}} · {{report.rows.total}}</span><Link v-if="report.rows.next_page_url" :href="report.rows.next_page_url" preserve-scroll>{{ $t('Next') }}</Link></nav><p>{{ $t("当前显示") }} {{report.rows.data.length}} / {{report.rows.total}} {{ $t("人") }}</p></section></main></admin-layout></template>
<script>
import { legacyText } from '@/Functions/LegacyTranslation';
import AdminLayout from '@/Layouts/AdminLayout';import '../../Umi/business.scss';export default{components:{AdminLayout},props:{report:Object,filters:Object},data(){return{query:this.filters?.search||'',result:this.filters?.result||'',names:{personal:legacyText("个人业绩"),team:legacyText("团队业绩"),small_area:legacyText("小区业绩"),rank:legacyText("等级"),today:legacyText("当日收益")}};},methods:{fmt(n){return n===null?legacyText("缺失"):String(n).replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,'');}}};</script>
